import React from 'react';
import { useTranslation } from 'react-i18next';
import { Link } from 'react-router-dom';
import type { CustomCellRendererProps } from 'ag-grid-react';
import type { ProdutoResumo } from '../services/produtoService';

export function ProdutoAcoesCell(props: CustomCellRendererProps<ProdutoResumo>): React.ReactElement | null {
  const { t } = useTranslation('common');
  const id = props.data?.id;
  if (id == null) {
    return null;
  }
  return (
    <Link
      to={`/admin/produtos/${id}`}
      className="text-sm font-medium text-sky-700 underline decoration-sky-600/40 underline-offset-2 hover:text-sky-900"
    >
      {t('modules.productsAdmin.editLink')}
    </Link>
  );
}
