import React from 'react';
import { useTranslation } from 'react-i18next';
import type { ProdutoFormValues } from '../types/produtoFormValues';

const inputBase =
  'w-full rounded-md border px-3 py-2 text-sm shadow-sm transition-colors focus:outline-none focus:ring-2 focus:ring-offset-0';
const inputNormal = `${inputBase} border-neutral-300 focus:border-sky-600 focus:ring-sky-500/25`;
const inputError = `${inputBase} border-red-500 focus:border-red-600 focus:ring-red-500/25`;

export type ProdutoFormProps = {
  values: ProdutoFormValues;
  onChange: (patch: Partial<ProdutoFormValues>) => void;
  errors: Record<string, string>;
  disabled?: boolean;
};

function FieldError({ message }: { message?: string }): React.ReactElement | null {
  if (!message) {
    return null;
  }
  return <p className="mt-1 text-sm text-red-600">{message}</p>;
}

function ProdutoForm(props: ProdutoFormProps): React.ReactElement {
  const { values, onChange, errors, disabled } = props;
  const { t } = useTranslation('common');
  const p = (name: keyof ProdutoFormValues) => (errors[name as string] ? inputError : inputNormal);

  const setSku = (index: number, patch: Partial<{ codigo: string; ativo: boolean }>) => {
    const next = values.skus.map((s, i) => (i === index ? { ...s, ...patch } : s));
    onChange({ skus: next });
  };

  const addSku = () => {
    onChange({ skus: [...values.skus, { codigo: '', ativo: true }] });
  };

  const removeSku = (index: number) => {
    if (values.skus.length <= 1) {
      return;
    }
    onChange({ skus: values.skus.filter((_, i) => i !== index) });
  };

  return (
    <div className="flex flex-col gap-8">
      <fieldset disabled={disabled} className="min-w-0">
        <legend className="mb-4 text-xs font-semibold uppercase tracking-wide text-neutral-500">
          {t('modules.productsAdmin.sectionIdentificacao')}
        </legend>
        <div className="grid grid-cols-1 gap-4 md:grid-cols-2 md:gap-6 lg:grid-cols-3 lg:gap-6">
          <div className="col-span-full md:col-span-2 lg:col-span-3">
            <label htmlFor="pf-nome" className="mb-1 block text-sm font-medium text-neutral-800">
              {t('modules.productsAdmin.fieldNome')}
            </label>
            <input
              id="pf-nome"
              type="text"
              autoComplete="off"
              className={p('nome')}
              value={values.nome}
              onChange={(e) => onChange({ nome: e.target.value })}
            />
            <FieldError message={errors.nome} />
          </div>

          <div className="col-span-full md:col-span-2 lg:col-span-3">
            <label htmlFor="pf-desc" className="mb-1 block text-sm font-medium text-neutral-800">
              {t('modules.productsAdmin.fieldDescricao')}
            </label>
            <textarea
              id="pf-desc"
              rows={3}
              className={`${p('descricao')} min-h-[5rem] resize-y`}
              value={values.descricao}
              onChange={(e) => onChange({ descricao: e.target.value })}
            />
            <FieldError message={errors.descricao} />
          </div>

          <div>
            <label htmlFor="pf-marca" className="mb-1 block text-sm font-medium text-neutral-800">
              {t('modules.productsAdmin.fieldMarca')}
            </label>
            <input
              id="pf-marca"
              type="text"
              autoComplete="off"
              className={p('marca')}
              value={values.marca}
              onChange={(e) => onChange({ marca: e.target.value })}
            />
            <FieldError message={errors.marca} />
          </div>

          <div>
            <label htmlFor="pf-modelo" className="mb-1 block text-sm font-medium text-neutral-800">
              {t('modules.productsAdmin.fieldModelo')}
            </label>
            <input
              id="pf-modelo"
              type="text"
              autoComplete="off"
              className={p('modelo')}
              value={values.modelo}
              onChange={(e) => onChange({ modelo: e.target.value })}
            />
            <FieldError message={errors.modelo} />
          </div>

          <div>
            <label htmlFor="pf-un" className="mb-1 block text-sm font-medium text-neutral-800">
              {t('modules.productsAdmin.fieldUnidade')}
            </label>
            <input
              id="pf-un"
              type="text"
              autoComplete="off"
              className={p('unidadeMedida')}
              value={values.unidadeMedida}
              onChange={(e) => onChange({ unidadeMedida: e.target.value })}
            />
            <FieldError message={errors.unidadeMedida} />
          </div>

          <div>
            <label htmlFor="pf-gtin" className="mb-1 block text-sm font-medium text-neutral-800">
              {t('modules.productsAdmin.fieldGtin')}
            </label>
            <input
              id="pf-gtin"
              type="text"
              autoComplete="off"
              className={p('gtin')}
              value={values.gtin}
              onChange={(e) => onChange({ gtin: e.target.value })}
            />
            <FieldError message={errors.gtin} />
          </div>
        </div>
      </fieldset>

      <fieldset disabled={disabled} className="min-w-0">
        <legend className="mb-4 text-xs font-semibold uppercase tracking-wide text-neutral-500">
          {t('modules.productsAdmin.sectionFiscalOrigem')}
        </legend>
        <div className="grid grid-cols-1 gap-4 md:grid-cols-2 md:gap-6 lg:grid-cols-3 lg:gap-6">
          <div>
            <label htmlFor="pf-origem" className="mb-1 block text-sm font-medium text-neutral-800">
              {t('modules.productsAdmin.fieldOrigemTipo')}
            </label>
            <input
              id="pf-origem"
              type="text"
              autoComplete="off"
              className={p('origemTipo')}
              value={values.origemTipo}
              onChange={(e) => onChange({ origemTipo: e.target.value })}
            />
            <FieldError message={errors.origemTipo} />
          </div>

          <div className="md:col-span-1 lg:col-span-2">
            <label htmlFor="pf-pais" className="mb-1 block text-sm font-medium text-neutral-800">
              {t('modules.productsAdmin.fieldPaisOrigem')}
            </label>
            <input
              id="pf-pais"
              type="text"
              autoComplete="off"
              className={p('paisOrigem')}
              value={values.paisOrigem}
              onChange={(e) => onChange({ paisOrigem: e.target.value })}
            />
            <FieldError message={errors.paisOrigem} />
          </div>

          <div className="lg:col-span-1">
            <label htmlFor="pf-ncm" className="mb-1 block text-sm font-medium text-neutral-800">
              {t('modules.productsAdmin.fieldNcm')}
            </label>
            <input
              id="pf-ncm"
              type="text"
              autoComplete="off"
              className={p('ncm')}
              value={values.ncm}
              onChange={(e) => onChange({ ncm: e.target.value })}
            />
            <FieldError message={errors.ncm} />
          </div>

          <div>
            <label htmlFor="pf-cest" className="mb-1 block text-sm font-medium text-neutral-800">
              {t('modules.productsAdmin.fieldCest')}
            </label>
            <input
              id="pf-cest"
              type="text"
              autoComplete="off"
              className={p('cest')}
              value={values.cest}
              onChange={(e) => onChange({ cest: e.target.value })}
            />
            <FieldError message={errors.cest} />
          </div>

          <div>
            <label htmlFor="pf-icms" className="mb-1 block text-sm font-medium text-neutral-800">
              {t('modules.productsAdmin.fieldOrigemIcms')}
            </label>
            <input
              id="pf-icms"
              type="text"
              autoComplete="off"
              className={p('origemIcms')}
              value={values.origemIcms}
              onChange={(e) => onChange({ origemIcms: e.target.value })}
            />
            <FieldError message={errors.origemIcms} />
          </div>
        </div>
      </fieldset>

      <fieldset disabled={disabled} className="min-w-0">
        <legend className="mb-4 text-xs font-semibold uppercase tracking-wide text-neutral-500">
          {t('modules.productsAdmin.sectionEmbalagem')}
        </legend>
        <div className="grid grid-cols-1 gap-4 sm:grid-cols-2 md:gap-6 lg:grid-cols-4 lg:gap-6">
          <div>
            <label htmlFor="pf-ea" className="mb-1 block text-sm font-medium text-neutral-800">
              {t('modules.productsAdmin.fieldEmbAltura')}
            </label>
            <input
              id="pf-ea"
              type="text"
              inputMode="decimal"
              autoComplete="off"
              className={p('alturaEmb')}
              value={values.alturaEmb}
              onChange={(e) => onChange({ alturaEmb: e.target.value })}
            />
            <FieldError message={errors.alturaEmb} />
          </div>
          <div>
            <label htmlFor="pf-el" className="mb-1 block text-sm font-medium text-neutral-800">
              {t('modules.productsAdmin.fieldEmbLargura')}
            </label>
            <input
              id="pf-el"
              type="text"
              inputMode="decimal"
              autoComplete="off"
              className={p('larguraEmb')}
              value={values.larguraEmb}
              onChange={(e) => onChange({ larguraEmb: e.target.value })}
            />
            <FieldError message={errors.larguraEmb} />
          </div>
          <div>
            <label htmlFor="pf-ec" className="mb-1 block text-sm font-medium text-neutral-800">
              {t('modules.productsAdmin.fieldEmbComprimento')}
            </label>
            <input
              id="pf-ec"
              type="text"
              inputMode="decimal"
              autoComplete="off"
              className={p('comprimentoEmb')}
              value={values.comprimentoEmb}
              onChange={(e) => onChange({ comprimentoEmb: e.target.value })}
            />
            <FieldError message={errors.comprimentoEmb} />
          </div>
          <div>
            <label htmlFor="pf-ep" className="mb-1 block text-sm font-medium text-neutral-800">
              {t('modules.productsAdmin.fieldEmbPeso')}
            </label>
            <input
              id="pf-ep"
              type="text"
              inputMode="decimal"
              autoComplete="off"
              className={p('pesoEmb')}
              value={values.pesoEmb}
              onChange={(e) => onChange({ pesoEmb: e.target.value })}
            />
            <FieldError message={errors.pesoEmb} />
          </div>
        </div>
      </fieldset>

      <fieldset disabled={disabled} className="min-w-0">
        <legend className="mb-4 text-xs font-semibold uppercase tracking-wide text-neutral-500">
          {t('modules.productsAdmin.sectionDimensaoProduto')}
        </legend>
        <div className="mb-4 flex flex-wrap items-center gap-3">
          <input
            id="pf-dim-toggle"
            type="checkbox"
            className="h-4 w-4 rounded border-neutral-300 text-sky-600 focus:ring-sky-500"
            checked={values.incluirDimProduto}
            onChange={(e) => onChange({ incluirDimProduto: e.target.checked })}
          />
          <label htmlFor="pf-dim-toggle" className="text-sm font-medium text-neutral-800">
            {t('modules.productsAdmin.fieldDimProdutoToggle')}
          </label>
        </div>
        {values.incluirDimProduto ? (
          <div className="grid grid-cols-1 gap-4 md:grid-cols-3 md:gap-6">
            <div>
              <label htmlFor="pf-da" className="mb-1 block text-sm font-medium text-neutral-800">
                {t('modules.productsAdmin.fieldDimPAltura')}
              </label>
              <input
                id="pf-da"
                type="text"
                inputMode="decimal"
                autoComplete="off"
                className={p('alturaP')}
                value={values.alturaP}
                onChange={(e) => onChange({ alturaP: e.target.value })}
              />
              <FieldError message={errors.alturaP} />
            </div>
            <div>
              <label htmlFor="pf-dl" className="mb-1 block text-sm font-medium text-neutral-800">
                {t('modules.productsAdmin.fieldDimPLargura')}
              </label>
              <input
                id="pf-dl"
                type="text"
                inputMode="decimal"
                autoComplete="off"
                className={p('larguraP')}
                value={values.larguraP}
                onChange={(e) => onChange({ larguraP: e.target.value })}
              />
              <FieldError message={errors.larguraP} />
            </div>
            <div>
              <label htmlFor="pf-dc" className="mb-1 block text-sm font-medium text-neutral-800">
                {t('modules.productsAdmin.fieldDimPComprimento')}
              </label>
              <input
                id="pf-dc"
                type="text"
                inputMode="decimal"
                autoComplete="off"
                className={p('comprimentoP')}
                value={values.comprimentoP}
                onChange={(e) => onChange({ comprimentoP: e.target.value })}
              />
              <FieldError message={errors.comprimentoP} />
            </div>
          </div>
        ) : null}
      </fieldset>

      <fieldset disabled={disabled} className="min-w-0">
        <legend className="mb-4 text-xs font-semibold uppercase tracking-wide text-neutral-500">
          {t('modules.productsAdmin.sectionSkus')}
        </legend>
        <FieldError message={errors.skus} />
        <ul className="flex flex-col gap-4">
          {values.skus.map((s, i) => (
            <li
              key={i}
              className="grid grid-cols-1 items-end gap-4 rounded-md border border-neutral-200 bg-neutral-50/80 p-4 md:grid-cols-12 md:gap-4"
            >
              <div className="md:col-span-5">
                <label htmlFor={`pf-sku-c-${i}`} className="mb-1 block text-sm font-medium text-neutral-800">
                  {t('modules.productsAdmin.fieldSkuCodigo')}
                </label>
                <input
                  id={`pf-sku-c-${i}`}
                  type="text"
                  autoComplete="off"
                  className={errors[`skuCodigo_${i}`] ? inputError : inputNormal}
                  value={s.codigo}
                  onChange={(e) => setSku(i, { codigo: e.target.value })}
                />
                <FieldError message={errors[`skuCodigo_${i}`]} />
              </div>
              <div className="flex flex-wrap items-center gap-3 md:col-span-4">
                <input
                  id={`pf-sku-a-${i}`}
                  type="checkbox"
                  className="h-4 w-4 rounded border-neutral-300 text-sky-600 focus:ring-sky-500"
                  checked={s.ativo}
                  onChange={(e) => setSku(i, { ativo: e.target.checked })}
                />
                <label htmlFor={`pf-sku-a-${i}`} className="text-sm font-medium text-neutral-800">
                  {t('modules.productsAdmin.fieldSkuAtivo')}
                </label>
              </div>
              <div className="flex md:col-span-3 md:justify-end">
                <button
                  type="button"
                  className="rounded-md border border-neutral-300 bg-white px-3 py-2 text-sm font-medium text-neutral-700 shadow-sm hover:bg-neutral-50 disabled:cursor-not-allowed disabled:opacity-50"
                  onClick={() => removeSku(i)}
                  disabled={values.skus.length <= 1}
                >
                  {t('modules.productsAdmin.removeSku')}
                </button>
              </div>
            </li>
          ))}
        </ul>
        <button
          type="button"
          className="mt-4 rounded-md border border-dashed border-neutral-300 bg-white px-4 py-2 text-sm font-medium text-neutral-700 hover:border-sky-400 hover:text-sky-800"
          onClick={addSku}
        >
          {t('modules.productsAdmin.addSku')}
        </button>
      </fieldset>
    </div>
  );
}

export default ProdutoForm;
